#nullable enable

using System.Reflection;
using Microsoft.Extensions.DependencyInjection;

namespace XpEng.Coder80.Infrastructure;

public static class RegistrationScanner {

    /// <summary>
    /// Scans one assembly and applies every registration it declares, in four steps:
    ///
    ///   1. [Register] attributes — a type declaring how it registers itself.
    ///   2. IAddRegistrations contributors — classes registering types they do not own.
    ///   3. Validation over the finished collection. Deliberately deferred to the end so
    ///      every conflict is reported at once rather than failing on the first.
    ///   4. IOverrideRegistrations contributors, each superseding what came before.
    ///
    /// A project referenced by two parents has AddRegistrations called twice, so its
    /// registrations appear twice. That is a harmless repeat, not a conflict, and step 3
    /// distinguishes them: identical descriptors are collapsed, differing ones throw.
    /// </summary>
    public static IServiceCollection ApplyRegistrations(IServiceCollection services, Assembly assembly) {
        var types = assembly.GetTypes().Where(t => t is { IsClass: true, IsAbstract: false }).ToList();

        // 1. Attribute-declared registrations.
        foreach (var type in types) {
            foreach (var attribute in type.GetCustomAttributes<RegisterAttribute>()) {
                var serviceType = attribute.ServiceType ?? type;
                switch (attribute.Lifetime) {
                    case ServiceLifetime.Singleton: services.AddSingleton(serviceType, type); break;
                    case ServiceLifetime.Scoped:    services.AddScoped(serviceType, type); break;
                    case ServiceLifetime.Transient: services.AddTransient(serviceType, type); break;
                }
            }
        }

        // 2. Contributors registering types they do not own.
        foreach (var type in types.Where(t => typeof(IAddRegistrations).IsAssignableFrom(t))) {
            var contributor = (IAddRegistrations)Activator.CreateInstance(type)!;
            contributor.AddRegistrations(services);
        }

        // 3. Validate once, over the finished collection. A group whose descriptors are all
        //    identical is the diamond-dependency repeat — collapse it. A group that differs
        //    in implementation or lifetime is a genuine conflict.
        var conflicts = services
            .GroupBy(descriptor => descriptor.ServiceType)
            .Where(group => group.Count() > 1)
            .Where(group => group.Select(d => (d.ImplementationType, d.Lifetime)).Distinct().Count() > 1)
            .ToList();

        if (conflicts.Count > 0) {
            string detail = string.Join(Environment.NewLine, conflicts.Select(group =>
                "  " + group.Key.FullName + " -> " +
                string.Join(", ", group.Select(d => (d.ImplementationType?.FullName ?? "(factory)") + " (" + d.Lifetime + ")"))));

            throw new InvalidOperationException(
                "Conflicting DI registrations in '" + assembly.GetName().Name + "':" + Environment.NewLine + detail + Environment.NewLine +
                "Use IOverrideRegistrations to replace a registration deliberately.");
        }

        CollapseDuplicates(services);

        // 4. Overrides, each replacing whatever the same service type was registered as.
        foreach (var type in types.Where(t => typeof(IOverrideRegistrations).IsAssignableFrom(t))) {
            var contributor = (IOverrideRegistrations)Activator.CreateInstance(type)!;
            contributor.ReplaceRegistrations(services);
        }

        CollapseDuplicates(services);

        return services;
    }

    /// <summary>Keeps only the LAST descriptor for each service type — appends win, which
    /// is what makes an override supersede what it replaces.</summary>
    private static void CollapseDuplicates(IServiceCollection services) {
        var groups = services
            .GroupBy(descriptor => descriptor.ServiceType)
            .Where(group => group.Count() > 1)
            .ToList();

        foreach (var group in groups) {
            foreach (var stale in group.Take(group.Count() - 1).ToList()) services.Remove(stale);
        }
    }
}
